package com.fidecode.biteflow.application.printing;import com.fidecode.biteflow.application.printing.dto.*;import com.fidecode.biteflow.domain.printing.entity.PrintRule;import com.fidecode.biteflow.domain.printing.repository.PrintRuleRepository;import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import java.util.UUID;@ApplicationScoped public class CreatePrintRuleUseCase{private final PrintRuleRepository repo;@Inject public CreatePrintRuleUseCase(PrintRuleRepository repo){this.repo=repo;}public PrintRuleResponse execute(UUID storeId, PrintRuleRequest request){var r=new PrintRule(storeId,request.name(),request.operation().toUpperCase(),request.documentType().toUpperCase(),UUID.fromString(request.printerId()));if(request.sectorId()!=null&&!request.sectorId().isBlank())r.routeToSector(UUID.fromString(request.sectorId()));if(request.active()!=null)r.changeActive(request.active());return PrintingDtoMapper.toResponse(repo.save(r));}}
